      "content": "{\n  \"name\": \"dsh-better-sidebar\",\n  \"version\": \"0.32.1\",\n  \"description\": \"Better Sidebar for DSH — file tree, editor, changes, tasks and side chat in one column, separate for every conversation. Configure it in Settings → Side card (bottom-left). Also exposes a service other plugins use to register sidebar tabs and file viewers.\",\n  \"type\": \"module\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/omdsh-dev/DSH-better-sidebar\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./client/service\": {\n      \"types\": \"./lib/types/client/service.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./client/api\": {\n      \"types\": \"./lib/types/client/service.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./src/*\": \"./src/*\",\n    \"./icon\": \"./icon.svg\",\n    \"./package.json\": \"./package.json\",\n    \"./locale/*.json\": \"./locale/*.json\"\n  },\n  \"engines\": {\n    \"node\": \">=20\"\n  },\n  \"packageManager\": \"pnpm@11.8.0\",\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-ui-sidebar-right\",\n        \"@deepseek-ai/dsh-client-modules\"\n      ],\n      \"platform\": \"web\"\n    },\n    \"manifestVersion\": 1\n  },\n  \"files\": [\n    \"lib/index.js\",\n    \"lib/client.js\",\n    \"lib/client-registry.js\",\n    \"lib/client-editor.js\",\n    \"lib/client-locale.js\",\n    \"lib/client-mermaid.js\",\n    \"lib/client-terminal.js\",\n    \"lib/types/**/*.d.ts\",\n    \"src\",\n    \"scripts/check-profile-host-tree.mjs\",\n    \"scripts/install.sh\",\n    \"scripts/install.ps1\",\n    \"cordis.patch.yml\",\n    \"detail\",\n    \"README.md\",\n    \"README_ZH.md\",\n    \"LICENSE\",\n    \"icon.svg\",\n    \"locale/*.json\"\n  ],\n  \"scripts\": {\n    \"build\": \"node scripts/build-mermaid-frame-asset.mjs && node -e \\\"require('node:fs').rmSync('lib',{recursive:true,force:true})\\\" && tsc -p tsconfig.build.json && tsdown\",\n    \"build:asset\": \"node scripts/build-mermaid-frame-asset.mjs\",\n    \"prepublishOnly\": \"pnpm build\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"bundle\": \"node scripts/build-mermaid-frame-asset.mjs && tsdown\",\n    \"watch\": \"node scripts/build-mermaid-frame-asset.mjs && tsdown --watch\",\n    \"prepare\": \"node scripts/build-mermaid-frame-asset.mjs && tsdown\",\n    \"test\": \"vitest run\",\n    \"test:windows\": \"vitest run --maxWorkers=1\",\n    \"test:mount\": \"bash scripts/e2e-mount.sh\",\n    \"test:mount:aggregate\": \"bash scripts/e2e-aggregate-mount.sh\",\n    \"clean\": \"node -e \\\"require('node:fs').rmSync('lib',{recursive:true,force:true})\\\"\",\n    \"check:consumer-types\": \"bash scripts/check-consumer-types.sh\",\n    \"check:engines\": \"node --experimental-strip-types scripts/win-engine-check.mjs --assert\",\n    \"lint\": \"eslint .\"\n  },\n  \"license\": \"MIT\",\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.1.0\",\n    \"@deepseek-ai/schemastery\": \">=3.18.5 <4\",\n    \"@deepseek-ai/dsh-agent\": \"^0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-client-locale\": \"^0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"^0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-input-trigger\": \"^0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"^0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"^0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-sidebar-right\": \"^0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"^0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-host-webserver\": \"^0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-llm\": \"^0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-session\": \"^0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-settings\": \"^0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-subagent\": \"^0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-tools\": \"^0.2.2-rc.2\",\n    \"@huanlin/dsh-plugin-better-locale\": \"^0.1.0\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@huanlin/dsh-plugin-better-locale\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-sidebar-right\": {\n      \"optional\": true\n    }\n  },\n  \"dependencies\": {\n    \"@codemirror/commands\": \"^6.10.4\",\n    \"@codemirror/lang-cpp\": \"^6.0.3\",\n    \"@codemirror/lang-css\": \"^6.3.1\",\n    \"@codemirror/lang-go\": \"^6.0.1\",\n    \"@codemirror/lang-html\": \"^6.4.12\",\n    \"@codemirror/lang-java\": \"^6.0.2\",\n    \"@codemirror/lang-javascript\": \"^6.2.5\",\n    \"@codemirror/lang-json\": \"^6.0.2\",\n    \"@codemirror/lang-markdown\": \"^6.5.2\",\n    \"@codemirror/lang-php\": \"^6.0.2\",\n    \"@codemirror/lang-python\": \"^6.2.1\",\n    \"@codemirror/lang-rust\": \"^6.0.2\",\n    \"@codemirror/lang-sql\": \"^6.10.0\",\n    \"@codemirror/lang-vue\": \"^0.1.3\",\n    \"@codemirror/lang-xml\": \"^6.1.0\",\n    \"@codemirror/lang-yaml\": \"^6.1.3\",\n    \"@codemirror/language\": \"^6.12.4\",\n    \"@codemirror/legacy-modes\": \"^6.5.3\",\n    \"@codemirror/search\": \"^6.7.1\",\n    \"@codemirror/state\": \"^6.7.1\",\n    \"@codemirror/view\": \"^6.43.8\",\n    \"@formkit/auto-animate\": \"^0.10.0\",\n    \"@lezer/highlight\": \"^1.2.3\",\n    \"@xterm/addon-fit\": \"^0.11.0\",\n    \"@xterm/xterm\": \"^6.0.0\",\n    \"clsx\": \"^2.1.1\",\n    \"dompurify\": \"^3.4.14\",\n    \"mermaid\": \"^11.16.1\",\n    \"react-icons\": \"5.7.0\",\n    \"rxjs\": \"^7.8.2\",\n    \"ws\": \"^8.18.0\",\n    \"yaml\": \"^2.9.1\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.1.0\",\n    \"@deepseek-ai/cordis-plugin-group\": \"~1.1.0\",\n    \"@deepseek-ai/cordis-plugin-include\": \"1.1.0\",\n    \"@deepseek-ai/dsh-agent\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-agent-loop\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-attachment\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-client-store\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-input-trigger\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-sidebar-right\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-error\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-host-webserver\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-llm\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-ptc-runtime\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-sandbox\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-sandbox-policy\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-scope\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-session\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-session-persistence\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-session-projection\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-settings\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-subagent\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-system-prompt\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-tools\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-user-approval\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-util-code-language\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-util-time\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-util-workspace-path\": \"0.2.2-rc.2\",\n    \"@deepseek-ai/dsh-working-directory\": \"0.2.2-rc.2\",\n    \"@cordisjs/plugin-loader\": \"^1.0.0-rc.5\",\n    \"@eslint/js\": \"^10.0.1\",\n    \"@huanlin/dsh-plugin-better-locale\": \"^0.1.0\",\n    \"@playwright/test\": \"^1.62.1\",\n    \"@shikijs/langs\": \"^4.3.1\",\n    \"@types/mdast\": \"^4.0.4\",\n    \"@types/node\": \"^24.0.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"~18.3.1\",\n    \"@types/ws\": \"^8.5.10\",\n    \"anser\": \"^2.3.5\",\n    \"cordis\": \"^4.0.0-rc.8\",\n    \"diff\": \"^9.0.0\",\n    \"eslint\": \"^10.9.1\",\n    \"eslint-plugin-react-hooks\": \"^7.1.1\",\n    \"globals\": \"^17.12.0\",\n    \"immer\": \"^10.1.1\",\n    \"jsdom\": \"^29.1.1\",\n    \"katex\": \"^0.16.47\",\n    \"lightningcss\": \"^1.32.0\",\n    \"mdast-util-from-markdown\": \"^2.0.3\",\n    \"mdast-util-gfm\": \"^3.1.0\",\n    \"mdast-util-math\": \"^3.0.0\",\n    \"micromark-core-commonmark\": \"^2.0.3\",\n    \"micromark-extension-gfm\": \"^3.0.0\",\n    \"micromark-extension-math\": \"^3.1.0\",\n    \"micromark-factory-space\": \"^2.0.1\",\n    \"micromark-util-character\": \"^2.1.1\",\n    \"micromark-util-classify-character\": \"^2.0.1\",\n    \"micromark-util-sanitize-uri\": \"^2.0.1\",\n    \"micromark-util-symbol\": \"^2.0.1\",\n    \"micromark-util-types\": \"^2.0.2\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"18.2.0\",\n    \"rolldown\": \"1.2.16\",\n    \"shiki\": \"^4.3.1\",\n    \"simple-icons\": \"^16.32.0\",\n    \"tsdown\": \"^0.22.2\",\n    \"typescript\": \"^5.6.0\",\n    \"typescript-eslint\": \"^8.69.0\",\n    \"unrun\": \"^0.2.39\",\n    \"vitest\": \"^4.1.8\",\n    \"zustand\": \"~4.4.7\"\n  },\n  \"icon\": \"./icon.svg\"\n}\n"
    },
    {
      "path": "cordis.patch.yml",
      "content": "# dsh-better-sidebar bundle patch\n#\n# This file is the `dsh.bundle.patch` layer of the published npm package: when\n# the plugin is installed through the official CLI —\n#\n#   dsh plugin --profile <name> add dsh-better-sidebar@<version>\n#\n# — the command reconciles `dsh.profile.bundles` against installed packages\n# and, seeing this declaration, appends `dsh-better-sidebar` to the bundle\n# stack. The profile boot then merges THIS patch (a single `insert` of the\n# plugin row) exactly like the manual cordis.patch.yml mount line used\n# before. No profile file edits needed — one command installs and mounts.\n#\n# If the profile still carries the old manual mount line in its own\n# cordis.patch.yml, remove it before switching to the bundle channel to\n# avoid double-mounting (two Node halves, two sidebars).\n#\n# The `config.shell` / `config.shellArgs` rows are gone with the plugin's own\n# terminal (DSH 0.1.6 ships its own right-Sidebar terminal, and its shell is\n# chosen from the shell menu there):\n#\n#   - insert:\n#       - id: better-sidebar\n#         name: 'dsh-better-sidebar'\n#\n# Aggregate double-mount guard: aggregate bundles (e.g. @linxin666/dsh-web-ui-all)\n# may already mount this package under their own entry id (e.g.\n# `web-ui-better-sidebar`). Two mounts register /sidebar/api twice and fail the\n# whole plugin tree at boot (\"duplicate prefix route\"). The `!!js` disabled\n# expression backs THIS row off when another *enabled* entry already mounts\n# `dsh-better-sidebar`; the aggregate instance then owns the sidebar. The\n# loader evaluates it when this row is processed (entry-list order, only rows\n# before this one are visible), so the aggregate bundle must precede this one\n# in `dsh.profile.bundles` — the standard install order, since `dsh plugin add`\n# appends new bundles last. The reverse order (this bundle before the\n# aggregate) is a known limitation: the guard cannot see rows that come after\n# it, and no runtime singleton guard is added. Same-id manual duplicates still\n# fail loudly at the loader as before.\n- insert:\n    - id: better-sidebar\n      name: 'dsh-better-sidebar'\n      disabled: !!js \"[...ctx.loader.entries()].some((e) => e.options.name === 'dsh-better-sidebar' && e.options.id !== 'better-sidebar' && !e.disabled)\"\n"
    },
    {
      "path": "src/client/index.tsx",
      "content": "/**\n * Client half of dsh-better-sidebar: resolves the user's \"Side card\"\n * preferences through the plugin's own fenced settings route, mounts the\n * right sidebar portal (inside an error boundary so a rendering failure\n * shows an error strip instead of a blank panel), and contributes the Side\n * card settings section to the DSH Settings shell. Requires the runtime's\n * slots and sessions services; the bundle itself is a module-table consumer\n * only (react + ui-primitives, all provided or inlined — the editor and\n * mermaid libraries arrive as lazy chunks).\n */\nimport { createElement } from 'react'\nimport { createRoot, type Root } from 'react-dom/client'\nimport type { Context } from '../context-types.ts'\nimport { createSidebarStore } from './state.ts'\nimport { createBetterSidebarService, matchUrlTarget } from './service.ts'\nimport { disposeSidechatSurfaces } from './sidechat-surface.ts'\nimport { revalidateChunksOnReactivate, setChunkModuleSystem } from './chunk-loader.ts'\nimport { registerBuiltins } from './builtins/index.ts'\nimport { Sidebar } from './Sidebar.tsx'\nimport { RenderBoundary } from './RenderBoundary.tsx'\nimport { createNativeTabRecords } from './native/tab-adapter.tsx'\nimport { registerNativeSurface } from './native/index.ts'\nimport { createNativeGuideCatalog } from './native/guide-catalog.ts'\nimport { registerBottomToggle } from './sidebar/bottom-toggle.tsx'\nimport { ContextDiagnosticsHost, createContextDiagnosticsHost, registerContextDiagnosticsUI } from './context-diagnostics-ui.tsx'\nimport { createNativeSurface } from './native/surface.ts'\nimport { isTargetAvailable, openInterceptedLink, registerLinkInterception, shouldTakeOverLink } from './link-intercept.ts'\nimport { registerImeGuard } from './ime-guard.ts'\nimport { registerQuoteSource } from './selection-quote.ts'\nimport { IconSideCardNav } from './icons.tsx'\nimport type { SettingsSectionIconOwnerProps } from '@deepseek-ai/dsh-client-ui-settings/client'\nimport { loadBootDecision } from './prefs.ts'\nimport { SideCardSection } from './SideCardSection.tsx'\nimport { api } from './api.ts'\nimport { LOCALE_NS, attachLocale, attachBetterLocale, t, zh, en } from './locales.ts'\nimport { loadChunk } from './chunk-loader.ts'\nimport css from './sidebar.module.css'\nimport './layout.css'\n\n/** Services required before mounting (provided by the client runtime; the\n *  locale service backs the sidebar's copy — see locales.ts). `modules`\n *  (rc.8+) is the client module system the chunk loader resolves its\n *  externals through; `connection` (0.1.2-alpha.2+) is the Remote transport's\n *  recovery lifecycle the side chat's disconnect banner reads — Cordis guards\n *  service access without inject.\n *\n *  `remote` / `remote.session` (0.1.7) are the Host Remote namespace the\n *  \"open in app\" adapter calls (`canOpenWorkspacePath` /\n *  `workspacePathApplications` / `openWorkspacePath`). BOTH entries are\n *  required: Cordis validates the nested property access\n *  (`ctx.get('remote').session`) against the inject list, and a missing\n *  entry throws `cannot get property \"remote.session\" without inject` —\n *  which, thrown from a render path, blanks the whole sidebar panel. */\nexport const inject = ['slots', 'sessions', 'locale', 'modules', 'connection', 'remote', 'remote.session']\n\n/**\n * Error boundary over the sidebar tree (root scope): a render error in the\n * sidebar SHELL itself must never blank the page silently — the shared\n * RenderBoundary shows a dismissible error strip and logs the stack. The\n * per-tab scope (Sidebar.tsx) catches viewer/editor crashes first; this root\n * boundary stays as the last resort for Workbench/shell errors.\n */\n/**\n * Client plugin body.\n * @param ctx - the client cordis context (slots, sessions).\n */\nexport function apply(ctx: Context): void {\n  // The sidebar follows the DSH i18n system: attach the locale service so\n  // the module-level t()/isZh() resolve the Host-backed language preference\n  // (and switch live — the Sidebar root subscribes to it), and register the\n  // plugin's dictionaries into the shared locale registry. The disposers\n  // run on fiber disposal, so re-activation (HMR) re-registers cleanly.\n  attachLocale(ctx.locale)\n  ctx.effect(() => {\n    const offZh = ctx.locale.register(LOCALE_NS, 'zh', zh)\n    const offEn = ctx.locale.register(LOCALE_NS, 'en', en)\n    return () => { offZh(); offEn() }\n  }, 'dsh-better-sidebar: dictionaries')\n\n  // Opt-in third-language support through @huanlin/dsh-plugin-better-locale.\n  // When that plugin is installed, it publishes `ctx.betterLocale` (the\n  // override store) and patches LocaleRuntime.prototype.lookup to consult\n  // it. We mirror the same override awareness into the sidebar's own `t()`:\n  // attachBetterLocale() makes t() consult the store's getOverride first,\n  // so the sidebar's chrome (which bypasses ctx.locale and calls t()\n  // directly) also switches to the override language. We also register\n  // the ja dict with the better-locale store so external callers of\n  // ctx.locale.lookup('betterSidebar', key) get the override text too.\n  //\n  // Activation-order-safe: ctx.get('betterLocale') is a non-reactive read\n  // (cordis only re-evaluates declared `inject` deps). If better-locale\n  // activates after better-sidebar, the initial read returns undefined.\n  // We subscribe to the locale revision — better-locale bumps it on\n  // activation (when a persisted override exists) and on every override\n  // switch — and re-check ctx.get on each bump, attaching + registering\n  // the ja dict once the store becomes available.\n  ctx.effect(() => {\n    let dispose: (() => void) | undefined\n    // Guards the async chunk registration below: a sync() re-run (or fiber\n    // disposal) that lands while the chunk is still in flight must render\n    // that registration moot.\n    let generation = 0\n    const sync = (): void => {\n      generation += 1\n      dispose?.()\n      dispose = undefined\n      const store = ctx.get('betterLocale') as\n        | {\n            readonly active: string | undefined\n            getOverride(dshActive: string, ns: string, key: string): string | undefined\n            isOverrideActive(dshActive: string): boolean\n            register(ns: string, dicts: Record<string, Record<string, string>>): () => void\n            subscribe(listener: () => void): () => void\n          }\n        | undefined\n      attachBetterLocale(store)\n      if (store !== undefined) {\n        // The 19 override dictionaries ride the lazy `locale` chunk: until\n        // it lands, the store has no betterSidebar entries and t() keeps\n        // the zh/en chain; the store's own revision bump on register\n        // re-renders the chrome once the dicts arrive.\n        const myGeneration = generation\n        void loadChunk('locale')\n          .then(mod => {\n            if (myGeneration !== generation) return\n            dispose = store.register(LOCALE_NS, mod.localeDicts as Record<string, Record<string, string>>)\n          })\n          .catch(() => { /* the dicts stay unregistered; the zh/en chain runs */ })\n      }\n    }\n    // Initial check (picks up the store if better-locale activated first).\n    sync()\n    // Re-check on every locale revision bump (better-locale bumps when it\n    // activates with a persisted override, and when the user switches).\n    const unsubscribe = ctx.locale.subscribe(sync)\n    return () => {\n      generation += 1\n      unsubscribe()\n      dispose?.()\n      attachBetterLocale(undefined)\n    }\n  }, 'dsh-better-sidebar: better-locale lazy integration')\n  // A failure anywhere in the client lifecycle must never take the app down\n  // silently: log with the plugin prefix and pin a visible diagnostic strip\n  // to the page so a blank panel is never the only symptom. This strip is\n  // the last-resort reporter (no CSS module is reachable from here), so its\n  // colors go through skin token chains with the previous hexes as the\n  // chain tails — worst case (no skin tokens on the page) it renders\n  // byte-identical to the old hardcoded bar, and any `--dsw-alias-*` skin\n  // re-themes it (guide §12: no hardcoded colors).\n  const fail = (phase: string, error: unknown): void => {\n    console.error(`[dsh-better-sidebar] ${phase} error:`, error)\n    try {\n      const bar = document.createElement('div')\n      bar.style.cssText = 'position:fixed;left:8px;bottom:8px;z-index:2147483000;max-width:70vw;padding:8px 12px;'\n        + 'font:12px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace;'\n        + 'color:var(--dsw-alias-state-error-primary,#f2a1a1);'\n        + 'background:var(--dsw-alias-bg-layer-3,var(--dsw-alias-bg-base,#1b1b22));'\n        + 'border:1px solid var(--dsw-alias-state-error-primary,#f2a1a1);border-radius:8px;white-space:pre-wrap'\n      bar.textContent = `[dsh-better-sidebar] ${phase} error: ${error instanceof Error ? error.message : String(error)}`\n      document.body.appendChild(bar)\n    } catch {\n      // Nothing left to report with.\n    }\n  }\n  // One store instance per activation: production code creates it only here,\n  // then hands it to the mounted panel and closes over it in the slot\n  // registrations (the official createXXXStore() factory rule — no\n  // module-level singleton).\n  const sidebarStore = createSidebarStore()\n  // The sidebar registry service: external plugins register tab types and\n  // file previewers through `ctx.betterSidebar.registerTab/registerFileViewer`.\n  // Published before the panel mounts so consumers injecting 'betterSidebar'\n  // are ready by the time the sidebar renders.\n  const service = createBetterSidebarService(sidebarStore)\n  ctx.provide('betterSidebar', service)\n  ctx.effect(() => () => { disposeSidechatSurfaces(service) }, 'dsh-better-sidebar: sidechat surface adapters')\n  // The native right-Sidebar surface: the plugin's content is registered as\n  // DSH tab types (one per descriptor) and every open routes there, so the\n  // right column belongs to the host and only the bottom workbench stays\n  // plugin-owned. Both halves live for this fiber's lifetime.\n  const nativeRecords = createNativeTabRecords()\n  // One live catalog of host guide cards, shared by the start-page takeover\n  // and the settings inventory. It subscribes to the host tab registry and is\n  // released with this activation.\n  const nativeGuide = createNativeGuideCatalog(ctx)\n  ctx.effect(() => () => { nativeGuide.dispose() }, 'dsh-better-sidebar: native guide catalog')\n  const nativeSurface = createNativeSurface(ctx, nativeRecords)\n  service.setSurface(nativeSurface)\n  // The optional dsh-context diagnostics: ONE controller per activation. It\n  // re-proves the optional runtime faces itself, so the plugin needs no new\n  // inject entry; it is threaded explicitly into the three consumers (the two\n  // host slots by closure, the plugin's own React tree through the provider,\n  // and the native tab bodies through the native surface's deps). On a\n  // deployment without dsh-context it reports `available: false` and every\n  // entry point stays absent.\n  const diagnostics = createContextDiagnosticsHost(ctx)\n  ctx.effect(\n    () => registerNativeSurface({\n      ctx, store: sidebarStore, service, records: nativeRecords, diagnostics,\n      guideCatalog: nativeGuide.catalog,\n      reportFailure: (phase, error) => { fail(`native ${phase}`, error) },\n    }),\n    'dsh-better-sidebar: native right-Sidebar registrations',\n  )\n  // The bottom workbench's expand/collapse button in DSH's session header\n  // (the header's corner seat belongs to the native sidebar's own control).\n  ctx.effect(\n    () => registerBottomToggle(ctx, sidebarStore),\n    'dsh-better-sidebar: bottom-workbench toggle',\n  )\n  ctx.effect(\n    () => () => { nativeSurface.dispose(); service.setSurface(undefined) },\n    